    /**
     * @ignore
     * @method
     * @name predictfun#parsePredictionPosition
     * @description parses a raw position row into the unified position structure
     * @param {object} position the raw position row
     * @param {object} [market] not used by predictfun parsePredictionPosition
     * @returns {object} a [position structure](https://docs.ccxt.com/#/?id=position-structure)
     */
    public Object parsePredictionPosition(Map<String, Object> position, Map<String, Object> market)
    {
        Map<String, Object> rawOutcome = (Map<String, Object>) this.safeDict(position, "outcome", new HashMap<String, Object>() {{}});
        Map<String, Object> rawMarket = (Map<String, Object>) this.safeDict(position, "market", new HashMap<String, Object>() {{}});
        String tokenId = this.safeString(rawOutcome, "onChainId");
        Object outcomeObj = this.outcomeForToken((String) (tokenId), market);
        // shares are collateral wei, the usd figures come back already scaled
        String contracts = Precise.stringDiv(this.safeString(position, "amount"), "1000000000000000000");
        String entryPrice = this.safeString(position, "averageBuyPriceUsd");
        String notional = this.safeString(position, "valueUsd");
        String pnl = this.safeString(position, "pnlUsd");
        // what the shares cost, which is also the collateral committed to the position
        String collateral = Precise.stringMul(entryPrice, contracts);
        String markPrice = null;
        if ((!java.util.Objects.equals(notional, null)) && (!java.util.Objects.equals(contracts, null)) && Precise.stringGt(contracts, "0"))
        {
            markPrice = Precise.stringDiv(notional, contracts);
        }
        String percentage = null;
        if ((!java.util.Objects.equals(pnl, null)) && (!java.util.Objects.equals(collateral, null)) && Precise.stringGt(collateral, "0"))
        {
            percentage = Precise.stringMul(Precise.stringDiv(pnl, collateral), "100");
        }
        // a settled outcome reports WON or LOST, an open one leaves the field null - and the
        // market can read RESOLVED while the outcome has not been marked yet, so the two are
        // tracked apart: the position is resolved, but which side won is not yet known
        String outcomeStatus = this.safeString(rawOutcome, "status");
        String marketStatus = this.safeString(rawMarket, "status");
        Boolean settled = (java.util.Objects.equals(outcomeStatus, "WON")) || (java.util.Objects.equals(outcomeStatus, "LOST"));
        Boolean resolved = Boolean.TRUE.equals(settled) || (java.util.Objects.equals(marketStatus, "RESOLVED")) || (java.util.Objects.equals(marketStatus, "SETTLED"));
        Object won = null;
        String settleFraction = null;
        String payout = null;
        if (Boolean.TRUE.equals(settled))
        {
            won = (java.util.Objects.equals(outcomeStatus, "WON"));
            settleFraction = ((Boolean.TRUE.equals(won))) ? "1" : "0";
            // a winning share redeems for one unit of collateral, a losing one for nothing
            payout = ((Boolean.TRUE.equals(won))) ? contracts : "0";
        }
        // pnl is realized once the market has resolved, unrealized while it is still trading
        String realizedPnl = null;
        String unrealizedPnl = pnl;
        if (Boolean.TRUE.equals(resolved))
        {
            realizedPnl = pnl;
            unrealizedPnl = null;
        }
        final String finalContracts = contracts;
        final String finalNotional = notional;
        final String finalUnrealizedPnl = unrealizedPnl;
        final String finalRealizedPnl = realizedPnl;
        final String finalCollateral = collateral;
        final String finalMarkPrice = markPrice;
        final String finalPercentage = percentage;
        final Object finalWon = won;
        final String finalSettleFraction = settleFraction;
        final String finalPayout = payout;
        return this.safePredictionPosition((Map<String, Object>) (new HashMap<String, Object>() {{
            put( "id", Predictfun.this.safeString(position, "id") );
            put( "timestamp", null );
            put( "datetime", null );
            put( "contracts", Predictfun.this.parseNumber(finalContracts) );
            put( "contractSize", 1 );
            put( "side", "long" );
            put( "notional", Predictfun.this.parseNumber(finalNotional) );
            put( "unrealizedPnl", Predictfun.this.parseNumber(finalUnrealizedPnl) );
            put( "realizedPnl", Predictfun.this.parseNumber(finalRealizedPnl) );
            put( "collateral", Predictfun.this.parseNumber(finalCollateral) );
            put( "entryPrice", Predictfun.this.parseNumber(entryPrice) );
            put( "markPrice", Predictfun.this.parseNumber(finalMarkPrice) );
            put( "lastPrice", null );
            put( "percentage", Predictfun.this.parseNumber(finalPercentage) );
            put( "resolved", resolved );
            put( "won", finalWon );
            put( "settleFraction", Predictfun.this.parseNumber(finalSettleFraction) );
            put( "payout", Predictfun.this.parseNumber(finalPayout) );
            put( "outcome", Predictfun.this.safeOutcomeSymbol((String) (null), outcomeObj) );
            put( "outcomeId", Predictfun.this.safeString(outcomeObj, "outcomeId", tokenId) );
            put( "label", Predictfun.this.safeString(outcomeObj, "label", Predictfun.this.safeStringUpper(rawOutcome, "name")) );
            put( "market", Predictfun.this.safeString(outcomeObj, "market") );
            put( "event", Predictfun.this.safeString(outcomeObj, "event") );
            put( "info", position );
        }}));
    }
