    /**
     * @ignore
     * @method
     * @name predictfun#parsePredictionOrder
     * @description parses a raw order, as returned by the create and the fetch endpoints, into a unified order
     * @param {object} order the raw order, with the signed contract order nested under 'order'
     * @param {object} [market] the outcome the order belongs to, resolved from the token id when omitted
     * @returns {object} an [order structure](https://docs.ccxt.com/#/?id=order-structure)
     */
    public Object parsePredictionOrder(Map<String, Object> order, Map<String, Object> market)
    {
        //
        // fetchOrder
        //     {
        //         "amount": "10000000000000000000",
        //         "amountFilled": "0",
        //         "currency": "USDT",
        //         "id": "415537",
        //         "isNegRisk": false,
        //         "isYieldBearing": true,
        //         "marketId": 2004048,
        //         "order": {
        //             "expiration": 1788717567,
        //             "feeRateBps": "200",
        //             "hash": "0xd0933a7528d1f4d8f82861a097a8e44298806f072a76bc9ec9c423707c94dfe7",
        //             "maker": "0x78C7b44105eB616B48d4A4328D4Ded1c3B53AF31",
        //             "makerAmount": "5000000000000000000",
        //             "nonce": "0",
        //             "salt": "1788713967425",
        //             "side": 0,
        //             "signature": "0x019cfd569d6d678a5ba900d43d93dfd55b3ef98c38d5b9bd243ac356a1fbffaa351e417d534195aa43bf20f07c6b82c25e7c49591f7c74565c3b9fa75b298bbb1c",
        //             "signatureType": 0,
        //             "signer": "0x78C7b44105eB616B48d4A4328D4Ded1c3B53AF31",
        //             "taker": "0x0000000000000000000000000000000000000000",
        //             "takerAmount": "10000000000000000000",
        //             "tokenId": "21794117812663370870023674333212505719146120894214542748572818978538793884650"
        //         },
        //         "rewardEarningRate": 0,
        //         "status": "CANCELLED",
        //         "strategy": "LIMIT"
        //     }
        //
        Map<String, Object> data = (Map<String, Object>) this.safeDict2(order, "order", "data");
        // the fetch endpoints nest the hash inside the contract order, the create endpoint
        // returns it at the top level as orderHash - accept either
        String topLevelHash = this.safeString2(order, "hash", "orderHash");
        String orderHash = this.safeString(data, "hash", topLevelHash);
        String tokenId = this.safeString(data, "tokenId");
        Object outcomeObj = this.outcomeForToken((String) (tokenId), market);
        // the contract order carries the economics: a buy offers collateral for shares while a
        // sell offers shares for collateral, so which leg is the size depends on the side
        String rawSide = this.safeString(data, "side");
        String side = null;
        if ((java.util.Objects.equals(rawSide, "0")) || (java.util.Objects.equals(rawSide, "Bid")))
        {
            side = "buy";
        } else if ((java.util.Objects.equals(rawSide, "1")) || (java.util.Objects.equals(rawSide, "Ask")))
        {
            side = "sell";
        }
        String makerAmount = this.safeString(data, "makerAmount");
        String takerAmount = this.safeString(data, "takerAmount");
        String amountWei = makerAmount;
        String costWei = takerAmount;
        if (java.util.Objects.equals(side, "buy"))
        {
            amountWei = takerAmount;
            costWei = makerAmount;
        }
        String amount = Precise.stringDiv(amountWei, "1000000000000000000");
        String cost = Precise.stringDiv(costWei, "1000000000000000000");
        String type = this.safeStringLower(order, "strategy");
        String price = null;
        // orders show same takerAmount and makerAmount as it was when they were placed
        // the price of market orders will be calculated incorrectly
        // we can calculate price for limit orders only
        if (java.util.Objects.equals(type, "limit"))
        {
            price = Precise.stringDiv(cost, amount);
        }
        String amountFilled = this.safeString(order, "amountFilled");
        String filled = Precise.stringDiv(amountFilled, "1000000000000000000");
        String filledCost = Precise.stringMul(filled, price);
        final String finalSide = side;
        final String finalPrice = price;
        return this.safePredictionOrder((Map<String, Object>) (new HashMap<String, Object>() {{
            put( "id", orderHash );
            put( "clientOrderId", null );
            put( "timestamp", null );
            put( "datetime", null );
            put( "status", Predictfun.this.parseOrderStatus(Predictfun.this.safeString(order, "status")) );
            put( "type", Predictfun.this.safeStringLower(order, "strategy") );
            put( "timeInForce", null );
            put( "side", finalSide );
            put( "price", finalPrice );
            put( "amount", amount );
            put( "filled", filled );
            put( "remaining", null );
            put( "cost", filledCost );
            put( "fee", null );
            put( "postOnly", Predictfun.this.safeBool(order, "isPostOnly") );
            put( "trades", null );
            put( "outcome", Predictfun.this.safeOutcomeSymbol((String) (tokenId), outcomeObj) );
            put( "outcomeId", Predictfun.this.safeString(outcomeObj, "outcomeId", tokenId) );
            put( "label", Predictfun.this.safeString(outcomeObj, "label") );
            put( "market", Predictfun.this.safeString(outcomeObj, "market") );
            put( "event", Predictfun.this.safeString(outcomeObj, "event") );
            put( "info", order );
        }}));
    }
